const font="";
export const textFontStyles="<style>@font-face{font-family:ExhibitionRokh;src:url('/static/rokh-fanum-medium.woff') format('woff');font-style:normal;font-weight:500;font-display:swap}body{font-family:ExhibitionRokh,Tahoma,sans-serif!important;font-weight:500}:where(p,a,button,input,select,textarea,label,small,summary,td,th,li,legend,figcaption,dt,dd,.terms-copy,.conditions-intro,.ticket-note,.ticket-status,.ticket-code,.ticket-cell:not(h1,h2,h3,h4,h5,h6)){font-family:ExhibitionRokh,Tahoma,sans-serif!important}:where(h1,h2,h3,h4,h5,h6){font-family:Vazirmatn,Tahoma,sans-serif}</style>";
export function textFontAsset(path){if(path!=='/static/rokh-fanum-medium.woff')return null;return new Response(Uint8Array.from(atob(font),c=>c.charCodeAt(0)),{headers:{'Content-Type':'font/woff','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}})}
